        b8[b7 >> 0x2] = ((aR['charCodeAt'](b7)| aR['charCodeAt']((b7+0x1)) << 0x8) | (aR['charCodeAt']((b7+0x2))<< 0x10)|(aR['charCodeAt'](b7 + 0x3)<<0x18));
    }
